{"explanation":"Rewrite the function as f(x) = 2 + 7/(x − 3). Its vertical asymptote is x = 3, where the function is undefined, and its horizontal asymptote is y = 2, which the graph approaches as x → ±∞. Move the slider to explore points on both branches.","manimCode":"const title = new MathTex({ latex: 'f(x)=\\frac{2x+1}{x-3}=2+\\frac{7}{x-3}' });
await title.waitForRender();
title.scale(0.85);
title.moveTo([0, 3.15, 0]);
await scene.play(new Write(title));

const ax = new Axes({
  xRange: [-6, 10, 2],
  yRange: [-7, 11, 2],
  xLength: 10,
  yLength: 4.8,
  tips: true
});
ax.moveTo([0, -0.35, 0]);
const axisLabels = ax.getAxisLabels();
await scene.play(new Create(ax));
scene.add(axisLabels);

function dashedSegment(a, b, color) {
  const pieces = [];
  const count = 36;
  for (let i = 0; i < count; i++) {
    const u = i / count;
    const v = (i + 0.55) / count;
    const start = a.map((n, j) => n + u * (b[j] - n));
    const end = a.map((n, j) => n + v * (b[j] - n));
    pieces.push(new Line({ start, end, color }));
  }
  return new VGroup(...pieces);
}

const vertical = dashedSegment(ax.c2p(3, -7), ax.c2p(3, 11), ORANGE);
const horizontal = dashedSegment(ax.c2p(-6, 2), ax.c2p(10, 2), GREEN);
const verticalLabel = new MathTex({ latex: 'x=3', color: ORANGE });
const horizontalLabel = new MathTex({ latex: 'y=2', color: GREEN });
await verticalLabel.waitForRender();
await horizontalLabel.waitForRender();
verticalLabel.scale(0.65).moveTo([0.65, 2.4, 0]);
horizontalLabel.scale(0.65).moveTo([5.55, -0.1, 0]);
await scene.play(new AnimationGroup([new FadeIn(vertical), new FadeIn(horizontal), new FadeIn(verticalLabel), new FadeIn(horizontalLabel)]));

const fn = x => 2 + 7 / (x - 3);
// Separate domains prevent connecting the branches across the pole.
// Trim each branch to the visible y range.
const leftBranch = ax.plot(fn, {
  xRange: [-6, 3 - 7 / 9], color: BLUE, numSamples: 600
});
const rightBranch = ax.plot(fn, {
  xRange: [3 + 7 / 9, 10], color: BLUE, numSamples: 600
});
await scene.play(new AnimationGroup([new Create(leftBranch), new Create(rightBranch)]));

const marker = new Dot({ point: ax.c2p(0, fn(0)), color: YELLOW });
scene.add(marker);
makeHoverable(marker, scene, { hoverScale: 1.4 });
let readout;
function updatePoint(value) {
  const atPole = Math.abs(value - 3) < 0.000001;
  const yValue = atPole ? null : fn(value);
  const visible = !atPole && yValue >= -7 && yValue <= 11;
  marker.setOpacity(visible ? 1 : 0);
  if (visible) marker.moveTo(ax.c2p(value, yValue));
  if (readout) scene.remove(readout);
  const message = atPole
    ? 'x = 3: undefined (vertical asymptote)'
    : 'x = ' + value.toFixed(2) + '    f(x) = ' + yValue.toFixed(2) + (visible ? '' : '    (outside view)');
  readout = new Text({ text: message, fontSize: 22, color: YELLOW });
  readout.moveTo([0, -3.3, 0]);
  scene.add(readout);
}
updatePoint(0);
const controls = new Controls(scene, { position: 'top-right', width: 230 });
controls.addSlider({ label: 'Explore x', min: -6, max: 10, value: 0, step: 0.05, onChange: updatePoint });
await scene.wait(999999);"}

